const raw = $json.data || "";
const lines = raw.split("\n").map(l => l.trim()).filter(Boolean);

if (lines.length < 2) {
  return [{ json: { error: "NO_DATA_RECEIVED" } }];
}

const latest = {};
let currentHeader = null;

// Parse CSV tables with dynamic headers
for (const line of lines) {
  if (!line) continue;

  // Detect header row
  if (line.startsWith(",result,table,")) {
    currentHeader = line.split(",").map(h => h.trim());
    continue;
  }

  if (!currentHeader) continue;

  const cols = line.split(",");
  const row = {};

  for (let i = 0; i < currentHeader.length; i++) {
    row[currentHeader[i]] = cols[i] !== undefined ? cols[i].trim() : "";
  }

  const topic = row["topic"];
  const value = parseFloat(row["_value"]);
  const time = new Date(row["_time"]);

  if (!topic || isNaN(value) || isNaN(time.getTime())) continue;

  if (!latest[topic] || time > latest[topic].time) {
    latest[topic] = { value, time };
  }
}

// Helper
function get(topic) {
  return latest[topic]?.value ?? null;
}

function getTime(topic) {
  return latest[topic]?.time ?? null;
}

// Find newest timestamp from all received data
let newestTime = null;

for (const topic of Object.keys(latest)) {
  const t = latest[topic].time;

  if (!newestTime || t > newestTime) {
    newestTime = t;
  }
}

// Freshness limit
// Example: if data is older than 30 minutes compared to newest received data,
// treat it as disconnected.
const DEFROST_MAX_AGE_MINUTES = 30;

function isStale(topic, maxAgeMinutes = DEFROST_MAX_AGE_MINUTES) {
  const topicTime = getTime(topic);

  if (!topicTime || !newestTime) return true;

  const ageMs = newestTime.getTime() - topicTime.getTime();
  const ageMinutes = ageMs / 1000 / 60;

  return ageMinutes > maxAgeMinutes;
}

// Helper for 1 / 0 defrost status
function defrostText(value, topic) {
  if (value === null || value === undefined) return "Signal Lost";

  if (isStale(topic)) return "Signal Lost";

  if (value === 1) return "Defrosting ON";
  if (value === 0) return "Defrosting OFF";

  return `UNKNOWN (${value})`;
}

/* Distances */
const chillerDoorDistance = get("1/11/ChD1/dist");
const coldroomDistance = get("PR/CR1/BRT38/DS1");

/* Status */
let chillerDoorStatus = "NO_DATA";
if (chillerDoorDistance !== null) {
  chillerDoorStatus = chillerDoorDistance > 0 ? "OPEN" : "CLOSED";
}

let coldroomStatus = "NO_DATA";
if (coldroomDistance !== null) {
  coldroomStatus = coldroomDistance > 0 ? "OPEN" : "CLOSED";
}

/* Keep old variable name */
const chillerDoorTemp = get("1/11/CrM1/tmp");
const CHILLER_door = chillerDoorTemp !== null ? chillerDoorTemp.toFixed(2) : null;

/* Activity / Defrost */
const activityTopic = "1/11/ETC11/def";
const activityValue = get(activityTopic);
const activity = defrostText(activityValue, activityTopic);

/* CR1B Defrost */
const cr1b1Topic = "1/1/CK3F1/def";
const cr1b2Topic = "1/1/CK3F2/def";
const cr1b3Topic = "1/1/CK3F3/def";

const cr1b1Value = get(cr1b1Topic);
const cr1b2Value = get(cr1b2Topic);
const cr1b3Value = get(cr1b3Topic);

const cr1b1 = defrostText(cr1b1Value, cr1b1Topic);
const cr1b2 = defrostText(cr1b2Value, cr1b2Topic);
const cr1b3 = defrostText(cr1b3Value, cr1b3Topic);

/* CB Rooms */
const cbRoom1Temperature = get("1/1/CB1M/tmp");
const cbRoom2Temperature = get("1/1/CB2M/tmp");

/* CB1 Blowers */
const cb1BlowerSet1 = {
  blower1: get("1/1/CB11/tmp"),
  blower2: get("1/1/CB12/tmp"),
  blower3: get("1/1/CB13/tmp"),
  blower4: get("1/1/CB14/tmp"),
};

const cb1BlowerSet2 = {
  blower5: get("1/1/CB15/tmp"),
  blower6: get("1/1/CB16/tmp"),
  blower7: get("1/1/CB17/tmp"),
  blower8: get("1/1/CB18/tmp"),
};

/* CB2 Blowers */
const cb2BlowerSet1 = {
  blower1: get("1/1/CB21/tmp"),
  blower2: get("1/1/CB22/tmp"),
  blower3: get("1/1/CB23/tmp"),
  blower4: get("1/1/CB24/tmp"),
};

const cb2BlowerSet2 = {
  blower5: get("1/1/CB25/tmp"),
  blower6: get("1/1/CB26/tmp"),
  blower7: get("1/1/CB27/tmp"),
  blower8: get("1/1/CB28/tmp"),
};

/* Cold Room 1 Door Temperature */
const c1DoorTemp = get("1/1/C1D1/tmp");
const C1_DOOR =
  c1DoorTemp !== null
    ? c1DoorTemp.toFixed(2)
    : null;

/* Blast 6 Door Temperature */
const b6DoorTemp = get("1/10/B6D1/tmp");
const B6_DOOR =
  b6DoorTemp !== null
    ? b6DoorTemp.toFixed(2)
    : null;

/* Blast 5 Door Temperature */
const b5DoorTemp = get("1/9/B5D1/tmp");
const B5_DOOR =
  b5DoorTemp !== null
    ? b5DoorTemp.toFixed(2)
    : null;

/* Cold Room 2 Door Temperature */
const c2DoorTemp = get("1/2/C2D1/tmp");
const C2_DOOR =
  c2DoorTemp !== null
    ? c2DoorTemp.toFixed(2)
    : null;

/* Cold Room 3 Door Temperature */
const c3DoorTemp = get("1/3/C3D1/tmp");
const C3_DOOR =
  c3DoorTemp !== null
    ? c3DoorTemp.toFixed(2)
    : null;

/* Cold Room 4 Door Temperature */
const c4DoorTemp = get("1/4/C4D1/tmp");
const C4_DOOR =
  c4DoorTemp !== null
    ? c4DoorTemp.toFixed(2)
    : null;

/* Blast 1 Door Temperature */
const b1DoorTemp = get("1/5/B1D1/tmp");
const B1_DOOR =
  b1DoorTemp !== null
    ? b1DoorTemp.toFixed(2)
    : null;

/* Blast 2 Door Temperature */
const b2DoorTemp = get("1/6/B2D1/tmp");
const B2_DOOR =
  b2DoorTemp !== null
    ? b2DoorTemp.toFixed(2)
    : null;

/* Blast 3 Door Temperature */
const b3DoorTemp = get("1/7/B3D1/tmp");
const B3_DOOR =
  b3DoorTemp !== null
    ? b3DoorTemp.toFixed(2)
    : null;

/* Blast 4 Door Temperature */
const b4DoorTemp = get("1/8/B4D1/tmp");
const B4_DOOR =
  b4DoorTemp !== null
    ? b4DoorTemp.toFixed(2)
    : null;

/* Loading Bay 1 Temperature */
const l1Temp = get("1/25/LB1/tmp");
const L1 =
  l1Temp !== null
    ? l1Temp.toFixed(2)
    : null;

/* Loading Bay 2 Temperature */
const l2Temp = get("1/25/LB2/tmp");
const L2 =
  l2Temp !== null
    ? l2Temp.toFixed(2)
    : null;

/* Production Temperature 1 */
const prodTemp1 = get("1/24/PE1/tmp");
const PRODTEMP1 =
  prodTemp1 !== null
    ? prodTemp1.toFixed(2)
    : null;

/* Production Temperature 2 */
const prodTemp2 = get("1/24/PE2/tmp");
const PRODTEMP2 =
  prodTemp2 !== null
    ? prodTemp2.toFixed(2)
    : null;

/* Production Temperature 3 */
const prodTemp3 = get("1/24/PE3/tmp");
const PRODTEMP3 =
  prodTemp3 !== null
    ? prodTemp3.toFixed(2)
    : null;

/* Production Temperature 4 - Marination Room */
const prodTemp4 = get("1/23/MR1/tmp");
const PRODTEMP4 =
  prodTemp4 !== null
    ? prodTemp4.toFixed(2)
    : null;

return [{
  json: {
    C1_DOOR,
    C2_DOOR,
    C3_DOOR,
    C4_DOOR,

    CHILLER_door,

    L1,
    L2,

    PRODTEMP1,
    PRODTEMP2,
    PRODTEMP3,
    PRODTEMP4,

    B1_DOOR,
    B2_DOOR,
    B3_DOOR,
    B4_DOOR,
    B5_DOOR,
    B6_DOOR,

    activityValue,
    activity,

    cr1b1Value,
    cr1b1,
    cr1b2Value,
    cr1b2,
    cr1b3Value,
    cr1b3,

    chillerDoorDistance,
    chillerDoorStatus,
    coldroomDistance,
    coldroomStatus,

    cbRoom1Temperature,
    cbRoom2Temperature,

    cb1Blowers: {
      set1: cb1BlowerSet1,
      set2: cb1BlowerSet2
    },

    cb2Blowers: {
      set1: cb2BlowerSet1,
      set2: cb2BlowerSet2
    }
  }
}];

const d = $json;

// ============================================================
// HELPERS
// ============================================================

// Format normal sensor values
function f(v) {
  return (v === null || v === undefined || v === "")
    ? "Signal Lost ⚠️"
    : v;
}

// Add °C only when temperature data exists
function temp(v) {
  return (v === null || v === undefined || v === "")
    ? "Signal Lost ⚠️"
    : `${v} °C`;
}

// Defrost status
function defrostDisplay(status, value) {
  if (status === "Signal Lost") return "Signal Lost ⚠️";
  if (status === "Defrosting ON") return "Defrosting ON 🟢";
  if (status === "Defrosting OFF") return "Defrosting OFF 🔴";

  // Fallback
  if (value === 1) return "Defrosting ON 🟢";
  if (value === 0) return "Defrosting OFF 🔴";

  return "Signal Lost ⚠️";
}

let msg = "";


// ============================================================
// 1. CHILLER BLAST
// ============================================================

msg += "🌡 <b>Chiller Blast</b>\n";
msg += `• CB 1: <b>${temp(d.cbRoom1Temperature)}</b>\n`;
msg += `• CB 2: <b>${temp(d.cbRoom2Temperature)}</b>\n\n`;


// ============================================================
// 2. CHILLER ROOM
// ============================================================

msg += "🌡 <b>Chiller Room</b>\n";
msg += `• Door: <b>${temp(d.CHILLER_door)}</b>\n`;
msg += `• Door Distance: <b>${f(d.chillerDoorDistance)}</b> (${f(d.chillerDoorStatus)})\n`;
msg += `• Activity: <b>${defrostDisplay(d.activity, d.activityValue)}</b>\n\n`;


// ============================================================
// 3. COLDROOMS
// ============================================================

msg += "🌡 <b>Coldrooms</b>\n";
msg += `• 1 Door: ${temp(d.C1_DOOR)}\n`;
msg += `• 2 Door: ${temp(d.C2_DOOR)}\n`;
msg += `• 3 Door: ${temp(d.C3_DOOR)}\n`;
msg += `• 4 Door: ${temp(d.C4_DOOR)}\n`;

msg += `• CR 1 Door Distance: <b>${f(d.coldroomDistance)}</b> (${f(d.coldroomStatus)})\n`;

msg += `• CR1B1: <b>${defrostDisplay(d.cr1b1, d.cr1b1Value)}</b>\n`;
msg += `• CR1B2: <b>${defrostDisplay(d.cr1b2, d.cr1b2Value)}</b>\n`;
msg += `• CR1B3: <b>${defrostDisplay(d.cr1b3, d.cr1b3Value)}</b>\n\n`;


// ============================================================
// 4. BLAST FREEZERS
// ============================================================

msg += "🌡 <b>Blast</b>\n";
msg += `• 1 Door: ${temp(d.B1_DOOR)}\n`;
msg += `• 2 Door: ${temp(d.B2_DOOR)}\n`;
msg += `• 3 Door: ${temp(d.B3_DOOR)}\n`;
msg += `• 4 Door: ${temp(d.B4_DOOR)}\n`;
msg += `• 5 Door: ${temp(d.B5_DOOR)}\n`;
msg += `• 6 Door: ${temp(d.B6_DOOR)}\n\n`;

// ============================================================
// 5. LOADING BAY
// ============================================================

msg += "🌡 <b>Loading Bay</b>\n";
msg += `• L1: ${temp(d.L1)}\n`;
msg += `• L2: ${temp(d.L2)}\n\n`;


// ============================================================
// 6. EXTENSION PRODUCTION AREA
// ============================================================

msg += "🌡 <b>Extension Production Area</b>\n";
msg += `• 1: ${temp(d.PRODTEMP1)}\n`;
msg += `• 2: ${temp(d.PRODTEMP2)}\n`;
msg += `• 3: ${temp(d.PRODTEMP3)}\n`;
msg += `• 4 (Marination Room): ${temp(d.PRODTEMP4)}\n`;


// ============================================================
// OUTPUT
// ============================================================

return {
  json: {
    message: msg
  }
};
